package com.lbos.commercecustomer.mapper; import com.lbos.commercecustomer.dto.client.partner.RetailerSummaryResponse;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.enums.InventoryStatus;import java.math.BigDecimal;import org.springframework.stereotype.Component; @Component public class CommerceMapper {public InventoryStatus inventory(int stock,Integer threshold){int effectiveThreshold=threshold==null?10:threshold;return stock==0?InventoryStatus.OUT_OF_STOCK:stock<=effectiveThreshold?InventoryStatus.LOW_STOCK:InventoryStatus.HEALTHY;}public CustomerResponse customer(CustomerProfile profile){return new CustomerResponse(profile.getId(),profile.getUserAccountId(),profile.getDateOfBirth(),profile.getProfileStatus(),profile.getRewardPointsBalance());}public AddressResponse address(CustomerAddress address,String cityName,String zoneName){return new AddressResponse(address.getId(),address.getCityId(),cityName,address.getZoneId(),zoneName,address.getAddressTag(),address.getLine1(),address.getLine2(),address.getPostalCode(),address.getLatitude(),address.getLongitude(),address.isDefaultAddress());}public CategoryResponse category(ProductCategory category){return new CategoryResponse(category.getId(),category.getName(),category.getDescription(),category.getStatus());}
  /** No retailer data available - every customer-facing caller should prefer the two-arg
   * overload below; this stays for callers (e.g. a retailer's own catalogue management view)
   * that don't need to show a shop badge on their own products. */
  public ProductResponse product(Product product){return product(product,null);}
  public ProductResponse product(Product product,RetailerSummaryResponse retailer){return new ProductResponse(product.getId(),product.getName(),product.getSku(),product.getCategory().getId(),product.getCategory().getName(),product.getRetailerId(),retailer==null?null:retailer.businessName(),retailer==null?null:retailer.retailerStatus(),retailer==null?null:retailer.latitude(),retailer==null?null:retailer.longitude(),product.getUnitPrice(),product.getStock(),product.getStatus(),inventory(product.getStock(),product.getLowStockThreshold()),product.getDescription(),product.getQualityFlag(),product.getLowStockThreshold(),product.effectiveWeightKg());}
  public ReviewResponse review(CustomerReview review){return new ReviewResponse(review.getId(),review.getOrderId(),review.getProduct()==null?null:review.getProduct().getId(),review.getRating(),review.getText(),review.getCreatedAt());}}